-- Все исторические отношения production_day—well сохранены с исходными формулами ключей.
WITH expected AS (SELECT DISTINCT lower(to_hex(md5(to_utf8('production_day_well:' || entity_id || ':' || json_extract_scalar(payload,'$.well_id'))))) AS link_hk,lower(to_hex(md5(to_utf8('production:' || entity_id)))) AS production_hk,lower(to_hex(md5(to_utf8('well:' || json_extract_scalar(payload,'$.well_id'))))) AS well_hk FROM {{target:oil_dds__event}} WHERE event_type='production_day'), actual AS (SELECT link_hk,production_hk,well_hk FROM {{target:oil_dds__link_production_day_well}}) SELECT count(*) AS n FROM ((SELECT * FROM expected EXCEPT ALL SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT ALL SELECT * FROM expected)) q;
